-- 复用平台菜单目录；新增字段缺省 PLATFORM，防止历史平台菜单变成登录公共入口。
ALTER TABLE platform_menu DROP CHECK ck_platform_menu_type;
ALTER TABLE platform_menu
 ADD COLUMN scope_type VARCHAR(20) NOT NULL DEFAULT 'PLATFORM' COMMENT '入口适用域；默认 PLATFORM，TENANT 要求有效租户成员，AUTHENTICATED 仅要求登录',
 ADD COLUMN external_url VARCHAR(2000) NULL COMMENT '外部链接 HTTP/HTTPS 绝对地址；默认 NULL，本地页面和目录不得填写，禁止凭据及脚本协议',
 ADD CONSTRAINT ck_platform_menu_type CHECK(type IN ('DIRECTORY','MENU','BUTTON','EXTERNAL')),
 ADD CONSTRAINT ck_platform_menu_scope CHECK(scope_type IN ('PLATFORM','TENANT','AUTHENTICATED'));

-- 初始化已交付页面的默认导航；不修改已有菜单，管理员可继续维护名称、同级顺序、显示和启用状态。
-- sort_order 单位为相对顺序，范围 0–9999；重复值由 code、id 提供稳定次序。
